def minimumSum(S):
    n = len(S)
    left = 0
    right = n - 1
    total_diff = 0

    while left < right:
        if S[left] != '?' and S[right] != '?' and S[left] != S[right]:
            return -1

        if S[left] == '?' and S[right] == '?':
            # Choose the character that minimizes the difference
            S[left] = S[right] = 'a'
        elif S[left] == '?':
            S[left] = S[right]
        elif S[right] == '?':
            S[right] = S[left]

        total_diff += abs(ord(S[left]) - ord(S[right]))
        left += 1
        right -= 1

    return total_diff
